/*
 * Module: clk_div
 * Project: RFID Tag FPGA Implementation (Arty S7)
 * * Description:
 * This module is the "Stage 2" clock divider in the Hybrid Clocking Strategy.
 * It takes the 5 MHz clock (generated by the FPGA's MMCM/PLL) and divides 
 * it down to the 200 kHz required by the RFID Tag logic.
 *
 * Clocking Math:
 * Input Frequency:  5,000,000 Hz (5 MHz)
 * Target Frequency: 200,000 Hz (200 kHz)
 * Division Factor:  5,000,000 / 200,000 = 25
 *
 * Logic:
 * A counter counts from 0 to 24 (25 cycles total).
 * - Output is HIGH for counts 0-12 (13 cycles)
 * - Output is LOW for counts 13-24 (12 cycles)
 * This creates a ~50% duty cycle clock.
 *
 * Ports:
 * clk_in  : 5 MHz Input Clock (from Clocking Wizard IP)
 * rst     : System Reset (Active High)
 * clk_out : 200 kHz Output Clock (to Tag Core)
 */

`timescale 1ns / 1ps

module clk_div(
    input wire clk_in,    // 5 MHz Input
    input wire rst,       // Active High Reset
    output reg clk_out    // 200 kHz Output
    );

    // We need to count to 25. 
    // 5 bits are required (2^5 = 32).
    reg [4:0] counter;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            counter <= 0;
            clk_out <= 0;
        end else begin
            // Count from 0 to 24
            if (counter >= 24) begin
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
            
            // Create the output clock (~52% High, 48% Low)
            // High for counts 0-12, Low for 13-24
            clk_out <= (counter < 13); 
        end
    end
endmodule